function timelineHtml(r) {
  const h = (r.history || []).slice();
  if (!h.length) return '<div class="tl-empty">変更履歴なし</div>';
  h.sort((a, b) => String(b.at || "").localeCompare(String(a.at || ""))); // newest first
  const li = h
    .map((e) => {
      const when = (e.at || "").replace("T", " ");
      const fld = HIST_FIELDS[e.field] || e.field || "";
      const from = e.from == null || e.from === "" ? "（空）" : e.from;
      const to = e.to == null || e.to === "" ? "（空）" : e.to;
      return (
        "<li><span class=\"when\">" + esc(when) + "</span>" +
        '<span class="fld">' + esc(fld) + "</span>: " +
        esc(from) + ' <span class="arrow">→</span> ' + esc(to) +
        (e.actor ? ' <span class="when">（' + esc(e.actor) + "）</span>" : "") +
        "</li>"
      );
    })
    .join("");
  return '<ul class="tl">' + li + "</ul>";
}

