const norm = (v) => (v == null ? "" : String(v));

// Commit a tracked field (status/owner/dueDate). Records history ONLY when the
// value actually changed; returns true if a write happened.
async function commitTracked(id, field, value) {
  const rec = ALL.find((r) => r.id === id);
  if (!rec) return false;
  if (norm(rec[field]) === norm(value)) return false; // no diff → no write, no history
  const entry = {
    at: new Date().toISOString().slice(0, 16),
    actor: ACTOR || "",
    field,
    from: norm(rec[field]),
    to: norm(value),
  };
  const history = (rec.history || []).concat([entry]);
  await save(id, { [field]: value, history });
  return true;
}

