function wire(root) {
  root.querySelectorAll(".taskrow").forEach((tr) => {
    const id = tr.getAttribute("data-id");
    // status via checkbox / dropdown → tracked (history)
    const chk = tr.querySelector('[data-act="toggle"]');
    if (chk) chk.addEventListener("change", () => commitTracked(id, "status", chk.checked ? "完了" : "未着手").then(render));
    const st = tr.querySelector('[data-act="status"]');
    if (st) st.addEventListener("change", () => commitTracked(id, "status", st.value).then(render));
    // owner / dueDate → tracked (history only if changed, on blur/change)
    const ow = tr.querySelector('[data-act="owner"]');
    if (ow) ow.addEventListener("change", () => commitTracked(id, "owner", ow.value).then(render));
    const du = tr.querySelector('[data-act="due"]');
    if (du) du.addEventListener("change", () => commitTracked(id, "dueDate", du.value).then(render));
    // memo → NOT tracked (no history), just persist
    const mm = tr.querySelector('[data-act="memo"]');
    if (mm) mm.addEventListener("change", () => save(id, { memo: mm.value }));
    // expander → toggle timeline
    const ex = tr.querySelector('[data-act="exp"]');
    if (ex)
      ex.addEventListener("click", () => {
        if (expanded.has(id)) expanded.delete(id);
        else expanded.add(id);
        const dr = root.querySelector('.detailrow[data-detail="' + CSS.escape(id) + '"]');
        if (dr) dr.classList.toggle("hidden");
        ex.textContent = expanded.has(id) ? "▾" : "▸";
      });
  });
  // override toggle lives on the detail row
  root.querySelectorAll('.detailrow [data-act="override"]').forEach((cb) => {
    const id = cb.closest(".detailrow").getAttribute("data-detail");
    cb.addEventListener("change", () => save(id, { overridden: cb.checked }).then(render));
  });
}

